CREATE VIEW IF NOT EXISTS {{database}}.aml_ingested_blocks_canonical AS SELECT network_id, block_number, data.1 AS block_hash, data.2 AS block_timestamp_unix_ms, data.3 AS commit_id, data.4 AS revision, data.5 AS parent_hash, data.6 AS canonical, data.7 AS ingestion_status, data.8 AS transaction_count, data.9 AS receipt_coverage, data.10 AS trace_coverage, data.11 AS prevout_coverage, data.12 AS source_id, data.13 AS created_at_unix_ms FROM (SELECT b.network_id AS network_id, b.block_number AS block_number, argMax(tuple(b.block_hash, b.block_timestamp_unix_ms, b.commit_id, b.revision, b.parent_hash, b.canonical, b.ingestion_status, b.transaction_count, b.receipt_coverage, b.trace_coverage, b.prevout_coverage, b.source_id, b.created_at_unix_ms), b.revision) AS data FROM {{database}}.aml_ingested_blocks AS b INNER JOIN {{database}}.aml_sync_state_current AS s ON b.network_id=s.network_id WHERE s.initialized=1 AND b.revision<=s.revision AND b.block_number<=s.last_block_number GROUP BY b.network_id,b.block_number) WHERE data.6=1 AND data.7='complete';

