CREATE VIEW IF NOT EXISTS {{database}}.aml_bitcoin_outputs_canonical AS SELECT f.network_id AS network_id, f.block_number AS block_number, f.block_hash AS block_hash, f.block_timestamp_unix_ms AS block_timestamp_unix_ms, f.commit_id AS commit_id, f.revision AS revision, f.tx_hash AS tx_hash, f.transaction_index AS transaction_index, f.output_index AS output_index, f.address AS address, f.script_hex AS script_hex, f.script_type AS script_type, f.value_sats AS value_sats, f.coinbase AS coinbase, f.created_at_unix_ms AS created_at_unix_ms FROM {{database}}.aml_bitcoin_outputs AS f FINAL INNER JOIN {{database}}.aml_ingested_blocks_canonical AS b ON f.network_id=b.network_id AND f.block_number=b.block_number AND f.block_hash=b.block_hash AND f.commit_id=b.commit_id AND f.revision=b.revision;

CREATE VIEW IF NOT EXISTS {{database}}.aml_evm_logs_canonical AS SELECT f.network_id AS network_id, f.block_number AS block_number, f.block_hash AS block_hash, f.block_timestamp_unix_ms AS block_timestamp_unix_ms, f.commit_id AS commit_id, f.revision AS revision, f.tx_hash AS tx_hash, f.log_index AS log_index, f.address AS address, f.topics AS topics, f.data AS data, f.created_at_unix_ms AS created_at_unix_ms FROM {{database}}.aml_evm_logs AS f FINAL INNER JOIN {{database}}.aml_ingested_blocks_canonical AS b ON f.network_id=b.network_id AND f.block_number=b.block_number AND f.block_hash=b.block_hash AND f.commit_id=b.commit_id AND f.revision=b.revision;

CREATE VIEW IF NOT EXISTS {{database}}.aml_tron_contracts_canonical AS SELECT f.network_id AS network_id, f.block_number AS block_number, f.block_hash AS block_hash, f.block_timestamp_unix_ms AS block_timestamp_unix_ms, f.commit_id AS commit_id, f.revision AS revision, f.tx_hash AS tx_hash, f.contract_index AS contract_index, f.contract_type AS contract_type, f.payload_json AS payload_json, f.created_at_unix_ms AS created_at_unix_ms FROM {{database}}.aml_tron_contracts AS f FINAL INNER JOIN {{database}}.aml_ingested_blocks_canonical AS b ON f.network_id=b.network_id AND f.block_number=b.block_number AND f.block_hash=b.block_hash AND f.commit_id=b.commit_id AND f.revision=b.revision;

CREATE VIEW IF NOT EXISTS {{database}}.aml_asset_metadata_current AS SELECT * FROM {{database}}.aml_asset_metadata ORDER BY revision DESC LIMIT 1 BY network_id,asset_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_metadata_jobs_current AS SELECT * FROM {{database}}.aml_metadata_jobs ORDER BY revision DESC LIMIT 1 BY network_id,job_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_ingestion_failures_current AS SELECT * FROM {{database}}.aml_ingestion_failures ORDER BY revision DESC LIMIT 1 BY network_id,failure_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_intelligence_sources_current AS SELECT * FROM {{database}}.aml_intelligence_sources ORDER BY revision DESC LIMIT 1 BY network_id,source_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_intelligence_claims_current AS SELECT * FROM {{database}}.aml_intelligence_claims ORDER BY revision DESC LIMIT 1 BY network_id,claim_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_cluster_claims_current AS SELECT * FROM {{database}}.aml_cluster_claims ORDER BY revision DESC LIMIT 1 BY network_id,claim_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_cluster_runs_current AS SELECT * FROM {{database}}.aml_cluster_runs ORDER BY revision DESC LIMIT 1 BY network_id,run_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_exposure_seeds_current AS SELECT * FROM {{database}}.aml_exposure_seeds ORDER BY revision DESC LIMIT 1 BY network_id,seed_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_exposure_runs_current AS SELECT * FROM {{database}}.aml_exposure_runs ORDER BY revision DESC LIMIT 1 BY network_id,run_id;

CREATE VIEW IF NOT EXISTS {{database}}.aml_wallet_risk_assessments_current AS SELECT * FROM {{database}}.aml_wallet_risk_assessments ORDER BY revision DESC LIMIT 1 BY network_id,assessment_id;

